package kr.releasepilot.controlplane.analysis;
import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;import tools.jackson.databind.*;import java.net.URI;import java.net.http.*;import java.time.Duration;
@Component public class HttpAnalysisWorkerGateway implements AnalysisWorkerGateway{
 private final HttpClient http;private final ObjectMapper json;private final String workerUrl;private final String sharedToken;
 public HttpAnalysisWorkerGateway(HttpClient http,ObjectMapper json,@Value("${releasepilot.analysis.worker-url:http://localhost:8090}")String workerUrl,@Value("${releasepilot.analysis.worker-shared-token:}")String sharedToken){this.http=http;this.json=json;this.workerUrl=workerUrl;this.sharedToken=sharedToken;}
 @Override public Result evaluate(Request r){try{if(sharedToken==null||sharedToken.isBlank())throw new IllegalStateException("Analysis Worker shared token is not configured");var body=json.createObjectNode();body.put("prometheus_url",r.prometheusUrl());if(r.bearerToken()!=null)body.put("bearer_token",r.bearerToken());body.put("source_id",r.sourceId());body.put("policy_snapshot_checksum",r.checksum());body.put("window_start",r.windowStart().toString());body.put("window_end",r.windowEnd().toString());var labels=body.putObject("labels");labels.put("service_namespace",r.serviceNamespace());labels.put("service_name",r.serviceName());labels.put("deployment_environment",r.environment());body.set("metrics",json.readTree(r.metricsJson()));var request=HttpRequest.newBuilder(URI.create(workerUrl+"/v1/analyses")).timeout(Duration.ofSeconds(30)).header("Content-Type","application/json").header("X-ReleasePilot-Worker-Token",sharedToken).POST(HttpRequest.BodyPublishers.ofString(json.writeValueAsString(body))).build();var response=http.send(request,HttpResponse.BodyHandlers.ofString());if(response.statusCode()<200||response.statusCode()>=300)throw new IllegalStateException("Analysis Worker returned HTTP "+response.statusCode());JsonNode result=json.readTree(response.body());return new Result(AnalysisVerdict.valueOf(result.path("verdict").asText()),result.path("reason_code").asText(),json.writeValueAsString(result.path("evidence")));}catch(InterruptedException e){Thread.currentThread().interrupt();throw new IllegalStateException("Analysis Worker request interrupted",e);}catch(Exception e){if(e instanceof IllegalStateException state)throw state;throw new IllegalStateException("Analysis Worker request failed",e);}}
 public Request withConfiguredWorker(Request r){return new Request(workerUrl,r.prometheusUrl(),r.bearerToken(),r.sourceId(),r.checksum(),r.windowStart(),r.windowEnd(),r.serviceNamespace(),r.serviceName(),r.environment(),r.metricsJson());}
}
